from typing import List

def adventureToCountMoves(numRows: int, numColumns: int, curRow: int, curColumn: int,
                          laserCoordinates: List[List[int]]) -> int:
    rows = {r for r, _ in laserCoordinates}
    cols = {c for _, c in laserCoordinates}

    def walk(start, step, limit, blocked):
        cnt, x = 0, start + step
        while 1 <= x <= limit and x not in blocked:
            cnt += 1
            x += step
        return cnt

    return max(walk(curRow, -1, numRows, rows), walk(curRow, 1, numRows, rows),
               walk(curColumn, -1, numColumns, cols), walk(curColumn, 1, numColumns, cols))
